# Add explicit absence notes for unverified scalar identities and dates.
for n,(path,o) in profiles.items():
    existing={g['field'] for g in o['verification_gaps']}
    for key in ['established','address','phone','email','admissions_url']:
        if o['identity'][key] is None and 'identity.'+key not in existing:
            o['verification_gaps'].append({'field':'identity.'+key,'reason':'No sufficiently clear official value was established in the sources read.','next_source':o['identity']['website']})
    if o['admissions']['dates']:
        o['verification_gaps']=[g for g in o['verification_gaps'] if g['field']!='admissions.dates']
    # Derive precise citation usage from actual section references.
    uses={s['id']:set() for s in o['sources']}
    def scan(v,p=''):
        if isinstance(v,dict):
            for k,x in v.items():
                if k=='sources':continue
                if k=='source_ids':
                    for ref in x:
                        assert ref in uses,(n,p,ref)
                        uses[ref].add(p)
                else:scan(x,(p+'.'+k).lstrip('.'))
        elif isinstance(v,list):
            for i,x in enumerate(v):scan(x,p+'.'+str(i))
    scan(o)
    for s in o['sources']:
        s['supports']=sorted(uses[s['id']]) or ['Research discovery or access limitation; no unsupported facts adopted']
    assert len(o['faqs'])>=5
    assert o['recognition']['icar_units'][0]['valid_from']
    assert o['editorial_status']=='research_draft'
    path.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

assert set(profiles)==set(range(1,21))
report=[]
for n,(p,o) in profiles.items():
    report.append({'id':n,'name':o['name'],'sources':len(o['sources']),'official_pages_read':sum(s['kind'] in ['official','affiliating_university'] and s['access']=='page_read' for s in o['sources']),'eligibility_present':o['programmes'][0]['eligibility'] is not None,'duration_present':o['programmes'][0]['duration'] is not None,'fee_verification':o['programmes'][0]['fees']['verification'],'gaps':len(o['verification_gaps'])})
(BASE/'coverage-report.md').write_text('# Batch 01 coverage — 30 October 2026\n\n20 institution profiles saved, IDs 1–20, with all contract sections and resolvable source references. All institutions received individual web searches and official-source retrieval attempts.\n\n| ID | Institution | Sources | Official pages read | Eligibility text | Duration text | Fee | Gaps |\n|---|---|---:|---:|---|---|---|---:|\n'+'\n'.join(f'| {r["id"]} | {r["name"]} | {r["sources"]} | {r["official_pages_read"]} | {"Yes" if r["eligibility_present"] else "Unverified"} | {"Yes" if r["duration_present"] else "Unverified"} | {r["fee_verification"]} | {r["gaps"]} |' for r in report)+'\n\nImportant limits: null fees remain deliberate where academic year or charge period could not be established. Khalsa College’s verified amount is historical 2024–25 only. Indexed official excerpts are explicitly labelled; JavaScript-only and image-only pages are not misrepresented as fully read. KCVAS and GHRU ICAR terms end on 8 November 2026. CU accreditation is programme-only; current agriculture intake needs confirmation. No CMS or application source changes.\n\nReproduction: run build_profiles.py, build_05_08.py, build_09_12.py, build_13_16.py, build_17_20.py, then enrich_final.py. The final JSON files include the enrichment pass.\n',encoding='utf-8')
print(json.dumps({'profiles':len(profiles),'sources':sum(r['sources'] for r in report),'eligibility_present':sum(r['eligibility_present'] for r in report),'duration_present':sum(r['duration_present'] for r in report),'named_faculty_profiles':sum(bool(o['faculty']['people']) for _,o in profiles.values()),'validation':'passed'},indent=2))
